[[nodiscard]] inline std::uint16_t unicode_flags(std::uint32_t cpt) {
    std::size_t lo = 0;
    std::size_t hi = sizeof(kUnicodeRanges) / sizeof(kUnicodeRanges[0]);
    while (lo + 1 < hi) {
        const std::size_t mid = (lo + hi) / 2;
        if (kUnicodeRanges[mid].start <= cpt) {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    std::uint16_t flags = kUnicodeRanges[lo].flags;
    std::size_t wlo = 0;
    std::size_t whi = sizeof(kUnicodeWhitespace) / sizeof(kUnicodeWhitespace[0]);
    while (wlo + 1 < whi) {
        const std::size_t mid = (wlo + whi) / 2;
        if (kUnicodeWhitespace[mid] <= cpt) {
            wlo = mid;
        } else {
            whi = mid;
        }
    }
    if (kUnicodeWhitespace[wlo] == cpt) {
        flags |= kUniWhitespace;
    }
    return flags;
}

